// @pit: {"label": "Commit PR C, push with retry, and open the pull request"}
async ({ delivery: { commit, listChangedFiles }, git: { push }, gh: { prCreate } }, p: { msg: string; title: string; body: string }) => {
  const files = (await listChangedFiles({ includeDeleted: true })).files;
  await commit({ files, message: p.msg });
  let r = await push(["-u", "origin", "fix/gh-api-json-capture"]);
  if (r.code) r = await push(["-u", "origin", "fix/gh-api-json-capture"]);
  if (r.code) return r;
  return { files, pr: (await prCreate({ base: "main", head: "fix/gh-api-json-capture", title: p.title, body: p.body })).stdout };
}
